$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest

$cssPath='src/assets/css/fm-global.css'
if(-not (Test-Path $cssPath)){throw "No existe $cssPath. Ejecutar desde la raiz del proyecto."}

$dirty=@(git status --porcelain -- $cssPath)
if($dirty.Count -gt 0){
  Write-Host ''
  Write-Host 'ABORTADO: fm-global.css ya tiene cambios locales.' -ForegroundColor Yellow
  Write-Host 'No se sobrescribio nada.' -ForegroundColor Yellow
  git status --short -- $cssPath
  exit 1
}

$fullPath=(Resolve-Path $cssPath).Path
$utf8NoBom=New-Object System.Text.UTF8Encoding($false)
$utf8Strict=New-Object System.Text.UTF8Encoding($false,$true)
$cp1252=[System.Text.Encoding]::GetEncoding(1252)
$commentRx=[regex]::new('/\*[\s\S]*?\*/')
$original=[System.IO.File]::ReadAllText($fullPath,[System.Text.Encoding]::UTF8)
$functionalBefore=$commentRx.Replace($original,'')

function Repair-MojibakeComment([string]$value){
  $sb=New-Object System.Text.StringBuilder
  $i=0
  while($i -lt $value.Length){
    $code=[int][char]$value[$i]
    $done=$false
    if(($code -eq 0x00C3 -or $code -eq 0x00C2) -and ($i+1 -lt $value.Length)){
      $code2=[int][char]$value[$i+1]
      if($code2 -le 255){
        try{
          $bytes=[byte[]]@([byte]$code,[byte]$code2)
          $decoded=$utf8Strict.GetString($bytes)
          [void]$sb.Append($decoded)
          $i+=2
          $done=$true
        }catch{}
      }
    }
    if(-not $done -and $code -eq 0x00E2 -and ($i+2 -lt $value.Length)){
      try{
        $segment=$value.Substring($i,3)
        $bytes=$cp1252.GetBytes($segment)
        $decoded=$utf8Strict.GetString($bytes)
        [void]$sb.Append($decoded)
        $i+=3
        $done=$true
      }catch{}
    }
    if(-not $done){[void]$sb.Append($value[$i]);$i++}
  }
  return $sb.ToString()
}

function Expand-DocPayload([string]$b64){
  $bytes=[Convert]::FromBase64String($b64)
  $input=New-Object System.IO.MemoryStream(,$bytes)
  $gzip=New-Object System.IO.Compression.GZipStream($input,[System.IO.Compression.CompressionMode]::Decompress)
  $reader=New-Object System.IO.StreamReader($gzip,[System.Text.Encoding]::UTF8)
  try{return ($reader.ReadToEnd() | ConvertFrom-Json)}finally{$reader.Dispose();$gzip.Dispose();$input.Dispose()}
}

function Replace-GeneralHeader([string]$text,[string]$newHeader){
  $start='/* === INICIO DOCUMENTACION GENERAL FM-GLOBAL === */'
  $end='/* === FIN DOCUMENTACION GENERAL FM-GLOBAL === */'
  $rx=[regex]::new([regex]::Escape($start)+'[\s\S]*?'+[regex]::Escape($end))
  if(-not $rx.IsMatch($text)){throw 'No se encontro la documentacion general esperada.'}
  return $rx.Replace($text,$newHeader,1)
}

function Replace-SectionDoc([string]$text,[string]$sectionName,[string]$doc){
  $section=[regex]::Escape("/* ===== INICIO: $sectionName ===== */")
  $docStart=[regex]::Escape('/* --- INICIO DOCUMENTACION DE SECCION --- */')
  $docEnd=[regex]::Escape('/* --- FIN DOCUMENTACION DE SECCION --- */')
  $rx=[regex]::new("($section\s*$docStart\s*)/\*[\s\S]*?\*/(\s*$docEnd)")
  if(-not $rx.IsMatch($text)){Write-Host "AVISO: sin bloque documentado para $sectionName" -ForegroundColor DarkYellow;return $text}
  return $rx.Replace($text,[System.Text.RegularExpressions.MatchEvaluator]{param($m)$m.Groups[1].Value+$doc+$m.Groups[2].Value},1)
}

function Replace-FirstCommentAfterSection([string]$text,[string]$sectionName,[string]$doc){
  $section=[regex]::Escape("/* ===== INICIO: $sectionName ===== */")
  $rx=[regex]::new("($section\s*)/\*[\s\S]*?\*/")
  if(-not $rx.IsMatch($text)){Write-Host "AVISO: sin comentario inicial para $sectionName" -ForegroundColor DarkYellow;return $text}
  return $rx.Replace($text,[System.Text.RegularExpressions.MatchEvaluator]{param($m)$m.Groups[1].Value+$doc},1)
}

$text=$commentRx.Replace($original,[System.Text.RegularExpressions.MatchEvaluator]{param($m) Repair-MojibakeComment $m.Value})

$payload=Expand-DocPayload '